  ('Julian Hart', 'Web Developer & UI Designer', array['Web Developer', 'UI Designer', 'Freelancer', 'Photographer']::text[], 'Creative developer based in Berlin, building fast and beautiful websites for brands, startups and people who love good design.', 'Hi, my name is Julian Hart. I have been designing and building websites for more than eight years, from simple landing pages to complete web apps with dashboards and online payments.
insert into public.services (title, short_description, icon_key, active, sort_order) values
  ('Web Development', 'Fast, secure websites and web apps built with modern tools and easy to update from a dashboard.', 'monitor', true, 1),
