insert into public.projects (title, slug, category, year, client, role, intro, challenge, solution, result, cover_image_url, gallery, live_url, likes, featured, status, sort_order) values
  ('Summit Outdoor Store', 'summit-outdoor-store', 'Web Design', 2026, 'Summit Gear', 'Design & Development', 'An online store for outdoor gear with quick checkout and a trip journal.', 'The client had a great product but an outdated website that was slow on mobile and hard to update. Visitors left before they understood what the product did.', 'We rewrote the key messages, designed a clean mobile-first layout and built it with a fast, modern stack. A simple dashboard lets the team edit every section on their own.', 'Pages now load in under a second, bounce rate dropped by a third and the team publishes new content every week without a developer.', '/demo/pf-mountains.svg', '["/demo/pf-mountains.svg","/demo/pf-workspace.svg"]'::jsonb, 'https://example.com', 240, true, 'published', 1),
  ('Lens & Light Studio', 'lens-and-light-studio', 'Photography', 2026, 'Lens & Light', 'Photography, Website', 'Portfolio website and photo shoot for a small photography studio.', 'The client had a great product but an outdated website that was slow on mobile and hard to update. Visitors left before they understood what the product did.', 'We rewrote the key messages, designed a clean mobile-first layout and built it with a fast, modern stack. A simple dashboard lets the team edit every section on their own.', 'Pages now load in under a second, bounce rate dropped by a third and the team publishes new content every week without a developer.', '/demo/pf-camera.svg', '["/demo/pf-camera.svg","/demo/pf-architecture.svg"]'::jsonb, null, 310, true, 'published', 2),
  ('Nord Coffee Identity', 'nord-coffee-identity', 'Branding', 2025, 'Nord Coffee', 'Brand Identity', 'Logo, packaging and a calm Nordic visual style for a speciality coffee brand.', 'The client had a great product but an outdated website that was slow on mobile and hard to update. Visitors left before they understood what the product did.', 'We rewrote the key messages, designed a clean mobile-first layout and built it with a fast, modern stack. A simple dashboard lets the team edit every section on their own.', 'Pages now load in under a second, bounce rate dropped by a third and the team publishes new content every week without a developer.', '/demo/pf-brand.svg', '["/demo/pf-brand.svg","/demo/pf-mobile.svg"]'::jsonb, null, 180, false, 'published', 3),
  ('Pulse Fitness App', 'pulse-fitness-app', 'Mobile App', 2025, 'Pulse', 'UI/UX Design', 'A workout tracker app with habit streaks and simple progress charts.', 'The client had a great product but an outdated website that was slow on mobile and hard to update. Visitors left before they understood what the product did.', 'We rewrote the key messages, designed a clean mobile-first layout and built it with a fast, modern stack. A simple dashboard lets the team edit every section on their own.', 'Pages now load in under a second, bounce rate dropped by a third and the team publishes new content every week without a developer.', '/demo/pf-mobile.svg', '["/demo/pf-mobile.svg","/demo/pf-brand.svg"]'::jsonb, 'https://example.com', 275, false, 'published', 4),
  ('Atlas Architects', 'atlas-architects', 'Web Design', 2024, 'Atlas Architects', 'Design & Development', 'A minimal portfolio website for an architecture office with large project galleries.', 'The client had a great product but an outdated website that was slow on mobile and hard to update. Visitors left before they understood what the product did.', 'We rewrote the key messages, designed a clean mobile-first layout and built it with a fast, modern stack. A simple dashboard lets the team edit every section on their own.', 'Pages now load in under a second, bounce rate dropped by a third and the team publishes new content every week without a developer.', '/demo/pf-architecture.svg', '["/demo/pf-architecture.svg","/demo/pf-mountains.svg"]'::jsonb, null, 205, false, 'published', 5),
  ('Remote Desk Dashboard', 'remote-desk-dashboard', 'Web Design', 2024, 'Remote Desk', 'Front-end Development', 'A booking dashboard for a co-working space with live desk availability.', 'The client had a great product but an outdated website that was slow on mobile and hard to update. Visitors left before they understood what the product did.', 'We rewrote the key messages, designed a clean mobile-first layout and built it with a fast, modern stack. A simple dashboard lets the team edit every section on their own.', 'Pages now load in under a second, bounce rate dropped by a third and the team publishes new content every week without a developer.', '/demo/pf-workspace.svg', '["/demo/pf-workspace.svg","/demo/pf-camera.svg"]'::jsonb, null, 190, false, 'published', 6);
